const https = require('https');

function fetch(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0', 'Accept': 'application/vnd.github.v3+json' } }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(JSON.parse(data)));
    }).on('error', reject);
  });
}

async function main() {
  const results = [];

  // Search 1: buff steam price compare
  const r1 = await fetch('https://api.github.com/search/repositories?q=buff+steam+price&sort=stars&per_page=15');

  // Search 2: buff 163 csgo trade
  const r2 = await fetch('https://api.github.com/search/repositories?q=buff163+csgo+trade&sort=stars&per_page=15');

  // Search 3: steam buff bot
  const r3 = await fetch('https://api.github.com/search/repositories?q=steam+buff+bot+price&sort=stars&per_page=15');

  // Search 4: buff market scraper
  const r4 = await fetch('https://api.github.com/search/repositories?q=buff+market+scraper+price&sort=stars&per_page=15');

  const allItems = [
    ...(r1.items || []),
    ...(r2.items || []),
    ...(r3.items || []),
    ...(r4.items || [])
  ];

  // Deduplicate by full_name
  const seen = new Set();
  const unique = allItems.filter(r => {
    if (seen.has(r.full_name)) return false;
    seen.add(r.full_name);
    return true;
  });

  // Sort by stars
  unique.sort((a, b) => b.stargazers_count - a.stargazers_count);

  const rows = unique.slice(0, 20).map(r => ({
    stars: r.stargazers_count,
    language: r.language || 'N/A',
    fullName: r.full_name,
    description: r.description || '',
    url: r.html_url,
    updatedAt: (r.updated_at || '').substring(0, 10)
  }));

  require('fs').writeFileSync(process.argv[process.argv.length - 1], JSON.stringify({ rows }, null, 2));
}

main().catch(console.error);

